// Every kind sam_get_entity_type can return AND sam_find_entities can filter on. ONE list,
// referenced by both, because they used to be written out separately 400 lines apart in this
// file and had drifted: the reader produced "gib" and "other" that the finder rejected, and the
// finder accepted "gold" that the reader never produced.
export const ENTITY_KINDS = ["any", "player", "monster", "item", "gold", "door", "chest", "fountain", "sink", "switch", "gate", "ladder", "portal", "boulder", "gib", "other"];

// The traits a mod may declare on an item, and the exact set sam_item_has_trait answers for.
// The runtime accepted four of these and refused the rest by name; four had no reader at all.
// The seven damage classes the engine has (DamageTableType). They are WEAPON CLASSES, not
// elements: Barony carries no fire/ice/lightning axis into the damage funnel at all, so a mod
// wanting "fire damage" picks a class here and keeps its own label.
// The nine values a stat modifier can contribute to. Deliberately NOT the whole stat list:
// LVL, GOLD, HUNGER and the rest are stored numbers rather than computed ones, so a modifier on
// them would be overwritten by the next write. Use sam_set_stat for those.
export const MODIFIABLE_STATS = ["STR", "DEX", "CON", "INT", "PER", "CHR", "AC", "ATTACK", "SPEED"];

export const DAMAGE_TYPES = ["sword", "mace", "axe", "polearm", "ranged", "magic", "unarmed"];

